"""Research paper analysis service."""

import json
import logging
from typing import Any

from pydantic import ValidationError

from app.prompts.research_prompts import build_paper_analysis_prompt
from app.schemas.analysis import PaperAnalysis
from app.services.llm_service import LLMServiceError, generate_response

logger = logging.getLogger(__name__)


class AnalysisServiceError(Exception):
    """Raised when paper analysis fails."""


def _parse_analysis_response(response: str) -> PaperAnalysis:
    """Parse and validate the JSON generated by the LLM."""

    cleaned_response = response.strip()

    # Handle responses wrapped in Markdown code fences.
    if cleaned_response.startswith("```"):
        lines = cleaned_response.splitlines()

        if lines and lines[0].startswith("```"):
            lines = lines[1:]

        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]

        cleaned_response = "\n".join(lines).strip()

        if cleaned_response.lower().startswith("json"):
            cleaned_response = cleaned_response[4:].strip()

    try:
        parsed: Any = json.loads(cleaned_response)
    except json.JSONDecodeError as exc:
        raise AnalysisServiceError(
            "The AI returned invalid JSON for the paper analysis."
        ) from exc

    if not isinstance(parsed, dict):
        raise AnalysisServiceError("The AI analysis must be a JSON object.")

    try:
        return PaperAnalysis.model_validate(parsed)
    except ValidationError as exc:
        logger.warning("LLM analysis did not match the expected schema.")
        raise AnalysisServiceError(
            "The AI analysis did not match the expected response format."
        ) from exc


def analyze_paper_text(paper_text: str) -> PaperAnalysis:
    """Analyze extracted research-paper text."""

    if not paper_text or not paper_text.strip():
        raise ValueError("Paper text cannot be empty.")

    prompt = build_paper_analysis_prompt(paper_text)

    try:
        response = generate_response(
            prompt=prompt,
            temperature=0.1,
        )
    except LLMServiceError as exc:
        raise AnalysisServiceError(
            "Could not generate the research paper analysis."
        ) from exc

    return _parse_analysis_response(response)
